import { gitText } from "./git-run";
import { atom, read, update } from "claude-code";
import type { EngineInterface, On, Timer } from "claude-code";

import type { AgentTree } from "../types";
import { AGENTS_TAB } from "./agents-tab";
import {
  completed,
  located,
  pruned,
  reconciled,
  spawned,
  stepped,
  toolEnded,
  toolStarted,
} from "./agents-model";
import type { Place } from "./agents-place";
import { directoryOf } from "./agents-place";
import { PANE } from "./pane-tab";
import {
  afterAgentRequest,
  BACKGROUND_OWNER,
  emptySpend,
  hasBaseline,
  SPEND_SESSIONS_KEY,
  withBaseline,
  withSession,
} from "./spend-model";
import { forgetShownTab, isShownTab, justEntered } from "./shown-tab";
import { folderName, isInside } from "./paths";
import { targetOf } from "./tools";

const FLUSH_DELAY_MS = 300;
const POLL_MS = 1000;
const PRESENT_AGENT_ID = /^(?!undefined$)./;

const agentsAtom = atom({ plugin: "paneline", key: "agents" } as const, {} as AgentTree);
const sessionUsdAtom = atom(
  { plugin: "paneline", key: "sessionUsd" } as const,
  null as number | null,
);

const spendAtom = atom({ plugin: "paneline", key: "spend" } as const, emptySpend());

let tree: AgentTree = {};
let seeding: Promise<void> | undefined;
let pendingFlush: Timer | undefined;
let poller: Timer | undefined;
let lastUsd: number | null | undefined;
const places = new Map<string, Place | null>();
const rootOfAgent = new Map<string, string>();

export function trackAgents(on: On): void {
  on("agent.spawn", async ($, e, next) => {
    const spawn = await next(e);
    if (spawn.agentId === undefined) return spawn;
    const agentId = spawn.agentId;
    const at = await $.clock.now();
    await record($, (current) =>
      spawned(current, {
        id: agentId,
        parentId: e.parentAgentId,
        type: e.subagentType,
        description: e.description,
        name: e.name,
        background: e.background,
        // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
        model: spawn.model ?? e.model ?? "",
        at,
      }),
    );
    if (isShownTab(AGENTS_TAB.id)) startPolling($);
    if (e.cwd !== undefined) await locate($, agentId, e.cwd);
    return spawn;
  });

  on("tool.call", { agentId: PRESENT_AGENT_ID }, async ($, e, next) => {
    const agentId = e.agentId;
    if (agentId === undefined) return next(e);
    const started = { callId: e.tool_use_id, tool: e.tool, target: targetOf(e) };
    await record($, (current) => toolStarted(current, agentId, started));
    try {
      return await next(e);
    } finally {
      await record($, (current) => toolEnded(current, agentId, e.tool_use_id));
      const dir = rootOfAgent.has(agentId) ? undefined : directoryOf(e);
      if (dir !== undefined) await locate($, agentId, dir);
    }
  });

  on("turn.step", { agentId: PRESENT_AGENT_ID }, async function* ($, e, next) {
    const startedAt = await $.clock.now();
    const step = yield* next(e);
    const agentId = e.agentId;
    if (agentId === undefined) return step;
    await record($, (current) =>
      stepped(current, agentId, {
        model: e.model,
        effort: e.effort?.toString(),
        usage: step.usage,
      }),
    );
    if (step.usage !== null) {
      const request = {
        agentId,
        index: e.index,
        usage: step.usage,
        startedAt,
        endedAt: await $.clock.now(),
      };
      const owner = tree[agentId]?.type ?? BACKGROUND_OWNER;
      const state = await update($, spendAtom, (current) =>
        afterAgentRequest(current, owner, request),
      );
      await $.store.set(
        SPEND_SESSIONS_KEY,
        withSession(await $.store.get(SPEND_SESSIONS_KEY), await $.session.id(), state),
      );
    }
    return step;
  });

  on("turn.complete", { agentId: PRESENT_AGENT_ID }, async ($, e, next) => {
    const agentId = e.agentId;
    if (agentId === undefined) return next(e);
    const at = await $.clock.now();
    await record($, (current) => completed(current, agentId, e.reason, at));
    await relocate($, agentId);
    return next(e);
  });

  on("ui.render", { component: "Pane", requestId: PANE }, ($, e, next) => {
    if (justEntered(AGENTS_TAB.id)) void watchAgents($);
    return next(e);
  });

  on("ui.close", { id: PANE }, async ($, e, next) => {
    forgetShownTab();
    stopPolling();
    return next(e);
  });

  on("session.measure", { changed: ["cost"] }, async ($, e, next) => {
    const usd = e.cost?.usd ?? null;
    if (usd !== lastUsd) {
      lastUsd = usd;
      await update($, sessionUsdAtom, () => usd);
      if (usd !== null) await settleBaseline($, usd);
    }
    return next(e);
  });

  on("classic.SessionStart", { source: "clear" }, async ($, e, next) => {
    stopPolling();
    places.clear();
    rootOfAgent.clear();
    await record($, () => ({}));
    return next(e);
  });
}

async function locate($: EngineInterface, agentId: string, dir: string): Promise<void> {
  if (!places.has(dir)) places.set(dir, await readPlace($, dir));
  const place = places.get(dir);
  if (!place) return;
  rootOfAgent.set(agentId, place.root);
  await showPlace($, agentId, place);
}

async function relocate($: EngineInterface, agentId: string): Promise<void> {
  const root = rootOfAgent.get(agentId);
  if (root === undefined) return;
  const place = await readPlace($, root);
  if (!place) return;
  places.set(root, place);
  await showPlace($, agentId, place);
}

async function showPlace(
  $: EngineInterface,
  agentId: string,
  { root, branch }: Place,
): Promise<void> {
  const isMainCheckout = isInside(await $.session.cwd(), root);
  await record($, (current) =>
    located(current, agentId, { branch, ...(!isMainCheckout && { worktree: folderName(root) }) }),
  );
}

async function readPlace($: EngineInterface, dir: string): Promise<Place | null> {
  const out = await gitText(
    {
      run: (argv) => $.process.run(argv),
      report: (error) => $.ui.log(`git failed: ${String(error)}`, { to: "debug" }),
    },
    dir,
    ["rev-parse", "--show-toplevel", "--abbrev-ref", "HEAD"],
  );
  const [root, branch] = out?.split("\n") ?? [];
  return root && branch ? { root, branch } : null;
}

async function record(
  $: EngineInterface,
  change: (current: AgentTree) => AgentTree,
): Promise<void> {
  await seeded($);
  const changed = change(tree);
  if (changed === tree) return;
  tree = changed;
  scheduleFlush($);
}

function seeded($: EngineInterface): Promise<void> {
  seeding ??= read($, agentsAtom).then((saved) => {
    tree = saved;
  });
  return seeding;
}

async function watchAgents($: EngineInterface): Promise<void> {
  await pollOnce($);
  startPolling($);
}

function startPolling($: EngineInterface): void {
  if (hasRunningAgent()) poller ??= $.clock.every(POLL_MS, () => void pollOnce($));
}

function stopPolling(): void {
  poller?.cancel();
  poller = undefined;
}

function hasRunningAgent(): boolean {
  return Object.values(tree).some((node) => node.status === "running");
}

async function pollOnce($: EngineInterface): Promise<void> {
  const [listed, at] = await Promise.all([$.agent.list(), $.clock.now()]);
  await record($, (current) => reconciled(current, listed, at));
  $.ui.invalidate("ui.render");
  if (!hasRunningAgent() || !isShownTab(AGENTS_TAB.id)) stopPolling();
}

function scheduleFlush($: EngineInterface): void {
  if (pendingFlush) return;
  pendingFlush = $.clock.after(FLUSH_DELAY_MS, () => {
    pendingFlush = undefined;
    tree = pruned(tree);
    void update($, agentsAtom, () => tree);
  });
}

async function settleBaseline($: EngineInterface, usd: number): Promise<void> {
  if (hasBaseline(await read($, spendAtom))) return;
  const state = await update($, spendAtom, (current) => withBaseline(current, usd));
  await $.store.set(
    SPEND_SESSIONS_KEY,
    withSession(await $.store.get(SPEND_SESSIONS_KEY), await $.session.id(), state),
  );
}

files.hooks/chat-render.tsx:
import { atom, memberOf, read, update } from "claude-code";
import type {
  EngineInterface,
  On,
  RenderElement,
  ResolveInput,
  UiPressArgument,
} from "claude-code";

import type { UsageSnap, PromptInfo } from "../types";
import { UNMEASURED_MS } from "./activity-track";
import { footerRow, layoutOf, toolGroupRow, userBlock } from "./chat-draw";
import type { ToolGroupView } from "./chat-draw";
import {
  bashChangesOf,
  bashNotes,
  diffPanel,
  fileChangeOf,
  withoutBashChanges,
} from "./diff-panel";
import type { BashChanges } from "./diff-panel";
import { replyView } from "./reply-draw";
import type { Accent } from "./pane-kit";
import { fillsFor } from "./palette";
import type { Fills } from "./palette";
import { metersOf, promptInfoRow } from "./prompt-info";
import { PANE } from "./pane-tab";
import { accentOf } from "./session-color";
import { TABS } from "./tabs";

const DIFF_TOOLS = new Set(["Edit", "Write"]);
const TYPED = new Set(["composer", "bridge", "sdk"]);
const MAX_PROMPT = 4000;
const MAX_REPLY_CHARS = 60_000;
const BAND_ROWS_WITH_SPACER = 2;
type Copy = (text: string, press: UiPressArgument) => void;

const usageAtom = atom(
  { plugin: "paneline", key: "usage" } as const,
  { context: null, limits: [] } as UsageSnap,
);
const promptInfoAtom = atom(
  { plugin: "paneline", key: "promptInfo" } as const,
  { model: "", effort: null, cwd: "" } as PromptInfo,
);
const sessionColorAtom = atom({ plugin: "paneline", key: "sessionColor" } as const, "default");
const themeAtom = atom({ plugin: "paneline", key: "theme" } as const, "dark");
const toolMsAtom = atom({ plugin: "paneline", key: "toolMs" } as const, UNMEASURED_MS);
const turnStatsAtom = atom({ plugin: "paneline", key: "turnStats" } as const, null);
const tabAtom = atom({ plugin: "paneline", key: "tab" } as const, "activity");

type RenderEvent = { surface: string; viewport?: { columns: number } };

async function elapsedOf($: EngineInterface, ids: (string | undefined)[]): Promise<number | null> {
  const known = ids.filter((id): id is string => id !== undefined && id !== "");
  const measured = (
    await Promise.all(known.map((id) => read($, memberOf(toolMsAtom, { requestId: id }))))
  ).filter((ms) => ms !== UNMEASURED_MS);
  return measured.length === 0 ? null : measured.reduce((sum, ms) => sum + ms, 0);
}

async function currentAccent($: EngineInterface): Promise<Accent> {
  return accentOf(await read($, sessionColorAtom));
}

async function currentFills($: EngineInterface): Promise<Fills> {
  return fillsFor(await read($, themeAtom));
}

async function openSessionPane($: EngineInterface): Promise<void> {
  await update($, tabAtom, () => TABS[0].id);
  await $.ui.open({ id: PANE, title: "Session", closeOnEscape: true });
}

async function toolRow(
  $: EngineInterface,
  e: ResolveInput & RenderEvent,
  ids: (string | undefined)[],
  view: Omit<ToolGroupView, "accent" | "fills">,
) {
  const [elapsedMs, accent, fills] = await Promise.all([
    elapsedOf($, ids),
    currentAccent($),
    currentFills($),
  ]);
  return toolGroupRow(
    $.ui.resolve(e),
    { ...view, elapsedMs, accent, fills },
    layoutOf(columnsOf(e)),
    () => void openSessionPane($),
  );
}

type FinishedCall = { tool_use_id: string; tool: string; output?: unknown; isErrored: boolean };
type CallEvent = ResolveInput & RenderEvent & { props: FinishedCall };
type Draw<E> = (e: E) => RenderElement | Promise<RenderElement>;

async function drawWithChanges<E extends CallEvent>(
  $: EngineInterface,
  e: E,
  next: Draw<E>,
): Promise<RenderElement> {
  const call = e.props;
  const changes = call.isErrored ? null : changesOf(call);
  if (changes === null) return next(e);
  const [{ cwd }, home, accent, fills] = await Promise.all([
    read($, promptInfoAtom),
    $.env.get("HOME"),
    currentAccent($),
    currentFills($),
  ]);
  const ui = $.ui.resolve(e);
  const windows = changes.changes.map((change) =>
    diffPanel(ui, {
      toolUseId: call.tool_use_id,
      change,
      cwd,
      home,
      width: layoutOf(columnsOf(e)).width,
      accent,
      fills,
    }),
  );
  if (call.tool !== "Bash") return windows[0] ?? next(e);
  const rest = await next({
    ...e,
    props: { ...call, output: withoutBashChanges(call.output) },
  });
  const { Box } = ui;
  return (
    <Box flexDirection="column">
      {rest}
      {windows}
      {bashNotes(ui, changes)}
    </Box>
  );
}

function changesOf({ tool, output }: FinishedCall): BashChanges | null {
  if (tool === "Bash") return bashChangesOf(output);
  const change = DIFF_TOOLS.has(tool) ? fileChangeOf(output) : null;
  return change === null ? null : { changes: [change], moreFiles: 0, isShared: false };
}

const columnsOf = (e: RenderEvent): number => e.viewport?.columns ?? 100;

const RENDER_HINT_SECTION = {
  id: "paneline:render-hint",
  scope: "session",
  text: [
    "Replies in this session are drawn as rich terminal graphics.",
    "Use pipe tables with alignment for comparisons.",
    "Use GitHub alerts (> [!NOTE], [!TIP], [!IMPORTANT], [!WARNING], [!CAUTION]) for things that must not be missed.",
    'Use fenced code with a language, and title="path" when the code belongs to a file.',
    "Commands the user should run go in fenced bash blocks.",
    "When a flow, sequence, state, schema or numeric series is easier to see than read, add one small ```mermaid block: flowchart, sequenceDiagram, stateDiagram, classDiagram, erDiagram, or xychart-beta with bar or line. Keep labels short.",
    "Skip the graphics for simple answers.",
  ].join(" "),
} as const;

export function renderChat(on: On): void {
  on("prompt.compose", async ($, e, next) => {
    const composed = await next(e);
    return { sections: [...composed.sections, RENDER_HINT_SECTION] };
  });

  const expandedCalls = new Set<string>();
  let copyWithLatest: Copy = () => {};

  const copy: Copy = (text, press) => copyWithLatest(text, press);

  on("ui.render", { component: "UserMessage" }, async ($, e, next) => {
    if (e.props.isExpanded || !TYPED.has(e.props.origin.kind) || e.props.text.length > MAX_PROMPT)
      return next(e);
    return userBlock($.ui.resolve(e), e.props.text, layoutOf(columnsOf(e)), await currentFills($));
  });

  on("ui.render", { component: "AssistantMessage" }, async ($, e, next) => {
    if (e.props.text.length > MAX_REPLY_CHARS) return next(e);
    copyWithLatest = (text, press) => {
      void $.ui
        .copy({ text, surface: press.surface })
        .then((result) => result.isCopied)
        .catch(() => false)
        .then((isCopied) => $.ui.toast(isCopied ? "Copied" : "Could not copy here"));
    };
    const { width } = layoutOf(columnsOf(e));
    const [accent, fills] = await Promise.all([currentAccent($), currentFills($)]);
    const request = {
      text: e.props.text,
      width,
      isFirstOfReply: e.props.isFirstOfReply,
      surface: e.surface,
      accent,
      fills,
    };
    return replyView($.ui.resolve(e), request, copy) ?? next(e);
  });

  on("ui.render", { component: "ToolGroup" }, ($, e, next) => {
    if (e.props.isExpanded) {
      e.props.calls.forEach((call) => call.tool_use_id && expandedCalls.add(call.tool_use_id));
      return next(e);
    }
    return toolRow(
      $,
      e,
      e.props.calls.map((call) => call.tool_use_id),
      { calls: e.props.calls, isActive: e.props.isActive, elapsedMs: null },
    );
  });

  on("ui.render", { component: "ToolUse" }, ($, e, next) => {
    if (expandedCalls.has(e.props.tool_use_id)) return drawWithChanges($, e, next);
    return toolRow($, e, [e.props.tool_use_id], {
      calls: [e.props],
      isActive: e.props.isRunning,
      elapsedMs: null,
    });
  });

  on("ui.render", { component: "ToolResult" }, ($, e, next) => drawWithChanges($, e, next));

  on("ui.render", { component: "TurnDuration" }, async ($, e) => {
    const [stats, fills] = await Promise.all([
      read($, memberOf(turnStatsAtom, { requestId: String(e.props.durationMs) })),
      currentFills($),
    ]);
    return footerRow(
      $.ui.resolve(e),
      e.props.durationMs,
      stats ?? undefined,
      layoutOf(columnsOf(e)),
      fills,
    );
  });

  on("ui.render", { component: "AbovePrompt" }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e);
    const [theirs, usage, info, home, color, nowMs] = await Promise.all([
      next(e),
      read($, usageAtom),
      read($, promptInfoAtom),
      $.env.get("HOME"),
      read($, sessionColorAtom),
      $.clock.now(),
    ]);
    const meters = metersOf(usage, nowMs);
    const ui = $.ui.resolve(e);
    const { Box } = ui;
    return (
      <Box flexDirection="column">
        {e.props.maxRows >= BAND_ROWS_WITH_SPACER ? <Box height={1} /> : null}
        {theirs}
        {promptInfoRow(ui, info, home, columnsOf(e), color, meters)}
      </Box>
    );
  });
}

